Lemma zbytes_skipn : forall i (bs : list byte), zbytes (skipn i bs) = skipn i (zbytes bs).
Proof. intros i bs. unfold zbytes. rewrite skipn_map. reflexivity. Qed.
Lemma skipn_cons_nth : forall {A} (l : list A) i x, nth_error l i = Some x -> skipn i l = x :: skipn (S i) l.
Proof.
  intros A l. induction l as [|y l IHl]; intros [|i] x H; cbn in *; try discriminate.
  - injection H as ->. reflexivity.
  - apply IHl. exact H.
Qed.

Lemma key_lt_eqlen : forall a b, length a = length b -> key_lt a b = ilex a b.
Proof. intros a b L. unfold key_lt. rewrite L. rewrite Z.ltb_irrefl. reflexivity. Qed.

Lemma lower_bound_loop_in : forall cmpL h S ns hd fuel r,
  rb_rep h S ns -> ns !! h = Some hd -> lower_bound_loop fuel cmpL ns (n_par hd) h = Some r -> r = h \/ r ∈ S.
Proof.
  intros cmpL h S ns hd fuel r (T & HS & HR) Lh LB.
  destruct (rep_hd _ _ _ HR) as (hd' & Lh' & Hp & _). rewrite Lh in Lh'. injection Lh' as <-.
  pose proof (lower_bound_loop_spec cmpL h T ns h (Nat.max fuel (theight T)) HR ltac:(lia)) as SPEC.
  assert (E : lower_bound_loop (Nat.max fuel (theight T)) cmpL ns (troot T) h = Some r).
  { rewrite <- Hp. unfold lower_bound_loop in *. destruct (n_par hd =? 0); [exact LB|].
    eapply oloop_mono; [exact LB| lia]. }
  rewrite SPEC in E. injection E as <-. rewrite <- HS. apply lbT_in.
Qed.

Lemma find_in : forall cmpL cmpU h S ns fuel r,
  rb_rep h S ns -> RBMem.find fuel cmpL cmpU ns h = Some r -> r = h \/ r ∈ S.
Proof.
  intros cmpL cmpU h S ns fuel r RR FD. unfold RBMem.find in FD.
  destruct (ns !! h) as [hd|] eqn:Lh. 2:{ unfold get_parent, load in FD. rewrite Lh in FD. discriminate. }
  rewrite (get_parent_eq _ _ _ Lh) in FD. cbn [mbind option_bind] in FD.
  destruct (lower_bound_loop fuel cmpL ns (n_par hd) h) as [y|] eqn:LBE; [| discriminate]. cbn [mbind option_bind] in FD.
  pose proof (lower_bound_loop_in _ _ _ _ _ _ _ RR Lh LBE) as YIN.
  destruct (y =? h); [injection FD as <-; left; reflexivity|].
  destruct (cmpU y); injection FD as <-; [left; reflexivity| exact YIN].
Qed.

(* [comment removed for export] *)
Definition ns_al (ns : NS) : Prop := forall a nd, ns !! a = Some nd -> 0 < a /\ a mod 8 = 0.

Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
(* [comment removed for export] *)

(* [comment removed for export] *)
Definition kc_res (a b : list byte) : Z := if key_lt (zbytes a) (zbytes b) then 1 else 0.

(* [comment removed for export] *)
Definition P_UB_LEXCMP : Z := 0x35ccc.

Definition lexcmp_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (l1 l2 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (Z.b2z (ilex (zbytes l1) (zbytes l2)))) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [] m m' /\ wmono usegs m m' /\ mem_inv usegs m' /\ m' = m.

Definition lexcmp_stmt : Prop := forall (p1 p2 : Z) (l1 l2 : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  bytes_at usegs m p1 l1 -> bytes_at usegs m p2 l2 ->
  p1 + zlength l1 < 2^64 -> p2 + zlength l2 < 2^64 ->
  (0 < zlength l1 -> 0 < zlength l2 -> 0 < p1 /\ 0 < p2) ->
  mem_inv usegs m ->
  evt usegs (lexcmp_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc l1 l2 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz p1) (wz (p1 + zlength l1)) (wz p2) (wz (p2 + zlength l2)) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_UB_LEXCMP) fc None m (seg_rom usegs)).
Scheme kc__2 := Elimination for Corelib.Init.Datatypes.option Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.
Scheme kc__4 := Elimination for Corelib.Init.Logic.and Sort Prop.
Scheme kc__5 := Elimination for Corelib.Init.Datatypes.list Sort Prop.

(* [comment removed for export] *)
Lemma lexcmp_loop : forall (cnt i : nat) (p1 p2 : Z) (l1 l2 : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (cnt = length l2 - i)%nat -> (i < length l2)%nat -> (i <= length l1)%nat ->
  ilex (zbytes l1) (zbytes l2) = ilex (zbytes (skipn i l1)) (zbytes (skipn i l2)) ->
  bytes_at usegs m p1 l1 -> bytes_at usegs m p2 l2 ->
  p1 + zlength l1 < 2^64 -> p2 + zlength l2 < 2^64 ->
  (0 < zlength l1 -> 0 < zlength l2 -> 0 < p1 /\ 0 < p2) ->
  mem_inv usegs m ->
  evt usegs (lexcmp_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc l1 l2 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (p1 + Z.of_nat i)) (wz (p1 + zlength l1)) (wz (p2 + Z.of_nat i)) (wz (p2 + zlength l2))
              (wz 1) (Z_to_bv 64 (-1)) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
