(* [comment removed for export] *)
Definition KCMP_STACK : Z := 16.

Definition kcmp1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (k nm : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (kc_res k nm)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp).

Definition kcmp1_stmt : Prop := forall (kp v : Z) (k nm : list byte) (rest : list cell) (lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  bytes_at usegs m kp k -> zlength k < 2^64 ->
  rw_cells usegs m v (C2 (wz (zlength nm + 2)) :: rest) ->
  bytes_at usegs m (v + 8) nm ->
  zlength nm + 2 < 2^16 ->
  (* [comment removed for export] *)
  v mod 8 = 0 -> 48 <= v -> v + 8 + zlength nm < 2^64 -> kp + zlength k < 2^64 -> (0 < zlength k -> 0 < kp) ->
  stk usegs m lo (bv_unsigned sp) -> lo + KCMP_STACK <= bv_unsigned sp ->
  (kp + zlength k <= lo \/ bv_unsigned sp <= kp) -> (v + 8 + zlength nm <= lo \/ bv_unsigned sp <= v) ->
  mem_inv usegs m ->
  evt usegs (kcmp1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc k nm lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (wz kp) (wz (zlength k)) (wz v) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_KEY_COMPARE_SV_VT) fc None m (seg_rom usegs)).
