Definition itto_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (res e lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (res, res + 8)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' res [C8 (wz e)].

Definition itto_stmt (entry : Z) : Prop := forall (res e nxt lo : Z) (rest : list cell) (rj : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells usegs m e (C8 (wz nxt) :: rest) -> 0 < nxt < 2^64 ->
  rw_cells usegs m res [CB 8 rj] ->
  stk usegs m lo (bv_unsigned sp) -> lo + 16 <= bv_unsigned sp -> hceil <= lo ->
  (e + Z.of_nat (cells_size (C8 (wz nxt) :: rest)) <= bv_unsigned sp - 16 \/ bv_unsigned sp <= e) ->
  (res + 8 <= bv_unsigned sp - 16 \/ bv_unsigned sp <= res) ->
  (e + Z.of_nat (cells_size (C8 (wz nxt) :: rest)) <= res \/ res + 8 <= e) ->
  0 < res ->                                                         (* [comment removed for export] *)
