(* [comment removed for export] *)
Lemma TreeR_node_al : forall m h S ns em x, TreeR m h S ns em -> x ∈ S -> 16 < x /\ x mod 8 = 0.
Proof.
  intros m h S ns em x TR IN. pose proof TR as (NC & EC & RR & SK & DOM & EOK & HHh & HB).
  destruct (TreeR_S_payload _ _ _ _ _ _ TR IN) as (d & Ld & _).
  pose proof (em_ok_range _ _ _ EOK Ld) as (P & A & _). split; [lia|].
  replace x with (x - 16 + 2 * 8) by lia. rewrite Z_mod_plus_full. exact A.
Qed.

(* [comment removed for export] *)
Lemma TreeR_ns_al : forall m h S ns em, TreeR m h S ns em -> h mod 8 = 0 -> ns_al ns.
Proof.
  intros m h S ns em TR HAL a nd L. pose proof TR as (NC & EC & RR & SK & DOM & EOK & HHh & HB). hcb.
  destruct (DOM a ltac:(rewrite L; eexists; reflexivity)) as [->|SM]; [split; [lia| exact HAL]|].
  destruct (em !! (a - 16)) as [d|] eqn:Ld; [| exfalso; exact (is_Some_None SM)].
  pose proof (em_ok_range _ _ _ EOK Ld) as (P & A & _). split; [lia|].
  replace a with (a - 16 + 2 * 8) by lia. rewrite Z_mod_plus_full. exact A.
Qed.

